args.sparql:
SELECT ?person ?personLabel ?dboBirth ?dbpBorn WHERE {
  VALUES ?person { dbr:John_Augustus_Conolly dbr:Abdel_Nasser_Barakat }
  OPTIONAL { ?person dbo:birthDate ?dboBirth. }
  OPTIONAL { ?person dbp:born ?dbpBorn. }
  OPTIONAL { ?person rdfs:label ?personLabel. FILTER (lang(?personLabel) = 'en') }
}

SELECT ?person ?personLabel ?dbpBirthDate WHERE {
  VALUES ?person { dbr:John_Augustus_Conolly }
  OPTIONAL { ?person dbp:birthDate ?dbpBirthDate. }
  OPTIONAL { ?person rdfs:label ?personLabel. FILTER(lang(?personLabel)='en') }
}

SELECT ?person ?personLabel ?birthDate WHERE {
  VALUES ?person { dbr:John_Augustus_Conolly dbr:Abdel_Nasser_Barakat }
  OPTIONAL { ?person dbo:birthDate ?dboBirth. }
  OPTIONAL { ?person dbp:birthDate ?dbpBirth. }
  BIND(COALESCE(?dboBirth, ?dbpBirth) AS ?birthDate)
  OPTIONAL { ?person rdfs:label ?personLabel. FILTER(lang(?personLabel)='en') }
}
ORDER BY DESC(?birthDate)
LIMIT 1

